from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(lambda universe: universe.include_weeklys().strikes(-50, 50).expiration(0, 365))
        self.option_symbol = option.symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.pending_entry = False
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.expiration_block_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.data_consolidated += self._on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy, consolidator)

    def _on_five_minute_bar(self, sender, bar):
        prior_ready = self.fast.is_ready and self.slow.is_ready
        prior_fast = self.fast.current.value if prior_ready else None
        prior_slow = self.slow.current.value if prior_ready else None

        self.fast.update(bar.end_time, bar.close)
        self.slow.update(bar.end_time, bar.close)

        if not prior_ready or not self.fast.is_ready or not self.slow.is_ready:
            return

        bar_time = bar.end_time.time()
        eligible_time = (
            bar_time >= datetime.strptime("09:45", "%H:%M").time()
            and bar_time <= datetime.strptime("14:30", "%H:%M").time()
        )

        if eligible_time and prior_fast <= prior_slow and self.fast.current.value > self.slow.current.value:
            self.pending_entry = True

    def on_data(self, slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_guard()
        self._evaluate_exit(slice)
        self._evaluate_pending_entry(slice)

    def _evaluate_pending_entry(self, slice):
        if not self.pending_entry:
            return

        self.pending_entry = False

        if self.expiration_block_date == self.time.date():
            return

        if self.held_symbol is not None and self.securities[self.held_symbol].invested:
            return

        if self.entry_ticket is not None and self.entry_ticket.status not in (
            OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID
        ):
            return

        chain = slice.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug("Entry skipped: no option chain")
            return

        minimum_expiry = self.time.date() + timedelta(days=7)
        eligible_expiries = sorted({
            contract.expiry.date()
            for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.debug("Entry skipped: no expiration >= 7 days")
            return

        selected_expiry = eligible_expiries[0]
        spy_price = self.securities[self.spy].price
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() == selected_expiry
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug("Entry skipped: no eligible call strike")
            return

        contract = min(candidates, key=lambda x: (x.strike, str(x.symbol)))
        self.held_expiry = contract.expiry
        self.entry_ticket = self.market_order(contract.symbol, 1)
        self.debug(f"Entry submitted: {contract.symbol}")

    def _evaluate_exit(self, slice):
        if self.held_symbol is None or not self.securities[self.held_symbol].invested:
            return

        if self._has_open_exit():
            return

        if self._is_pre_expiration_time_stop():
            self._submit_exit("pre-expiration time stop")
            return

        quote = slice.quote_bars.get(self.held_symbol)
        if quote is None or quote.bid is None or quote.ask is None:
            return

        bid = quote.bid.close
        ask = quote.ask.close
        if bid <= 0 or ask <= 0 or self.entry_fill_price is None:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None or self._has_open_exit():
            return

        self.transactions.cancel_open_orders(self.held_symbol)
        quantity = self.securities[self.held_symbol].holdings.quantity
        if quantity != 0:
            self.exit_ticket = self.market_order(self.held_symbol, -quantity)
            self.debug(f"Exit submitted ({reason}): {self.held_symbol}")

    def _handle_expiration_guard(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.time.date() >= self.held_expiry.date():
            self.expiration_block_date = self.time.date()
            if self.securities[self.held_symbol].invested:
                self._submit_exit("expiration guard")

    def _is_pre_expiration_time_stop(self):
        if self.held_expiry is None or self.time.time() != datetime.strptime("15:45", "%H:%M").time():
            return False

        candidate = self.held_expiry.date() - timedelta(days=1)
        exchange_hours = self.securities[self.spy].exchange.hours

        for _ in range(10):
            local_midnight = datetime.combine(candidate, datetime.min.time())
            if exchange_hours.is_date_open(local_midnight, False):
                return self.time.date() == candidate
            candidate -= timedelta(days=1)

        return False

    def _handle_unexpected_spy_position(self):
        spy_holding = self.securities[self.spy].holdings
        if spy_holding.quantity == 0:
            return

        open_orders = self.transactions.get_open_orders(self.spy)
        if not open_orders:
            self.market_order(self.spy, -spy_holding.quantity)
            self.debug("Unexpected SPY exercise/assignment position liquidated")

    def _has_open_exit(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.status not in (
                OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID
            )
        )

    def on_order_event(self, order_event):
        if self.entry_ticket is not None and order_event.order_id == self.entry_ticket.order_id:
            if order_event.status == OrderStatus.FILLED and order_event.fill_quantity > 0:
                self.held_symbol = order_event.symbol
                self.entry_fill_price = order_event.fill_price
                self.debug(f"Entry filled: {order_event.symbol} @ {order_event.fill_price}")

            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.entry_ticket = None
                self.held_expiry = None

        if self.exit_ticket is not None and order_event.order_id == self.exit_ticket.order_id:
            if order_event.status == OrderStatus.FILLED:
                if not self.securities[order_event.symbol].invested:
                    self.debug(f"Exit filled: {order_event.symbol} @ {order_event.fill_price}")
                    self.held_symbol = None
                    self.held_expiry = None
                    self.entry_fill_price = None
                    self.exit_ticket = None

