from datetime import datetime, time, timedelta

from QuantConnect import DataNormalizationMode, OptionRight, OrderStatus, Resolution, TimeZones
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Consolidators import TradeBarConsolidator
from QuantConnect.Indicators import RollingWindow


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-200, 200, 0, 365)
        self.option_canonical = option.Symbol

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry = False

        self.held_symbol = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_price = None
        self.expiry_date = None
        self.expiration_block_date = None
        self.spy_liquidation_order_id = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        current_fast = sum(self.fast_window[i] for i in range(5)) / 5.0
        current_slow = sum(self.slow_window[i] for i in range(20)) / 20.0

        if self.previous_fast is not None:
            bar_time = bar.EndTime.time()
            crossed_up = (
                self.previous_fast <= self.previous_slow
                and current_fast > current_slow
            )
            eligible_time = time(9, 45) <= bar_time <= time(14, 30)

            if crossed_up and eligible_time:
                self.pending_entry = True

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpiration(data)
        self.HandleOptionExit(data)

        if self.pending_entry:
            self.pending_entry = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.expiration_block_date == self.Time.date():
            return

        if self.held_symbol is not None or self.entry_order_id is not None:
            return

        chain = data.OptionChains.get(self.option_canonical)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped - no option chain.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped - invalid SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug(f"{self.Time}: Entry skipped - no expiration at least 7 calendar days away.")
            return

        selected_expiry = expiries[0]
        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= spy_price * 1.01
        ]

        if not candidates:
            self.Debug(f"{self.Time}: Entry skipped - no qualifying call for {selected_expiry}.")
            return

        selected = min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.held_symbol = selected.Symbol
            self.expiry_date = selected.Expiry.date()
            self.Debug(f"{self.Time}: Entry submitted {selected.Symbol}.")

    def HandleOptionExit(self, data):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.expiry_date is not None:
            previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
                datetime.combine(self.expiry_date, time.min)
            ).date()

            if self.Time.date() == previous_trading_day and self.Time.time() >= time(15, 45):
                self.SubmitExit("time stop")
                return

        if self.entry_price is None or self.exit_order_id is not None:
            return

        quote = data.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)
        if bid <= 0 or ask <= 0:
            return

        if (bid + ask) / 2.0 >= self.entry_price * 1.5:
            self.SubmitExit("profit target")

    def HandleExpiration(self, data):
        if self.held_symbol is None or self.expiry_date is None:
            return

        if self.Time.date() >= self.expiry_date:
            self.expiration_block_date = self.Time.date()
            if self.Portfolio[self.held_symbol].Quantity != 0:
                self.SubmitExit("expiration safeguard")

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.Transactions.CancelOrder(order.Id)

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        if ticket is not None:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"{self.Time}: Exit submitted for {self.held_symbol} ({reason}).")

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.spy_liquidation_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -quantity)
        if ticket is not None:
            self.spy_liquidation_order_id = ticket.OrderId
            self.Debug(f"{self.Time}: Unexpected SPY exercise/assignment position; liquidation submitted.")

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled {self.held_symbol} at {self.entry_price}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"{self.Time}: Entry order did not fill.")
                self.entry_order_id = None
                self.held_symbol = None
                self.entry_price = None
                self.expiry_date = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled {self.held_symbol} at {float(order_event.FillPrice)}."
                )
                if self.held_symbol is not None and self.Portfolio[self.held_symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None
                    self.expiry_date = None
                    self.exit_order_id = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

        if order_event.OrderId == self.spy_liquidation_order_id:
            if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                self.spy_liquidation_order_id = None

